<template>
  <div class="config-panel">
    <!-- 基础配置区域 -->
    <div class="basic-config">
      <div class="panel-header">
        <div class="panel-title">{{ t('imageEdit') }}</div>
        <p class="panel-description">{{ t('uploadImagesToUseImageEdit') }}</p>
      </div>

      <!-- 图片上传区域 -->
      <div class="form-section upload-section">
        <p class="upload-description">{{ t('uploadImageOrProvideUrl') }}</p>
        <UploadImage
          width="100%"
          height="200px"
          :max-size="4.5"
          :need-compression="true"
          :default-url="formdata.uploadedImageUrl"
          @uploadSuccess="handleUploadSuccess"
          @deleteSuccess="handleDeleteSuccess"
          ref="uploadImageRef"
        />
      </div>

      <!-- 图片涂抹区域 -->
      <div v-if="formdata.uploadedImageUrl" class="form-section">
        <div class="mask-section">
          <label class="form-label mask-label">{{ t('maskRequired') }}</label>
          <p class="form-help mask-help">{{ t('drawOnImageToDefineArea') }}</p>
          
          <!-- 图片涂抹画布 -->
          <div class="mask-canvas-container">
            <div class="canvas-wrapper" ref="canvasWrapper">
              <div class="canvas-container">
              <!-- 原始图片 -->
              <l-img
                :src="formdata.uploadedImageUrl"
                class="original-image"
                @onLoad="onImageLoad"
                w='100%'
                :h='"auto"'
                radius="4px"
                fit='contain'
              >
              
            </l-img>
              <div class="close-mask-button" @click="removeUploadedImage">
              <l-img w="20px" h="20px" src="/static/images/close_icon.png" />
            </div>

              </div>
             
              <!-- 涂抹画布 -->
              <canvas
                ref="maskCanvas"
                class="mask-canvas"
                @mousedown="startDrawing"
                @mousemove="draw"
                @mouseup="stopDrawing"
                @mouseleave="stopDrawing"
                @touchstart="handleTouchStart"
                @touchmove="handleTouchMove"
                @touchend="handleTouchEnd"
                @contextmenu="preventDefault"
              ></canvas>
              
            </div>
            
            <!-- 涂抹工具栏 -->
            <div class="mask-toolbar">
              <div class="toolbar-icons">
                <div class="tool-icon" @click="handleUndoMask" >
                  <l-img w="20px" h="20px" src="/static/images/draw-pre-icon.png" />
                </div>
                <div class="tool-icon" @click="handleRedoMask">
                  <l-img w="20px" h="20px" src="/static/images/draw-next-icon.png" />
                </div>
                <div class="tool-icon" @click="handleClearMask">
                  <l-img w="20px" h="20px" src="/static/images/draw-clear-icon.png" />
                </div>
                <div class="tool-icon" @click="handleDownloadMask">
                  <l-img w="20px" h="20px" src="/static/images/draw-down-icon.png" />
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      <!-- 提示词区域 -->
      <div class="form-section">
        <div class="prompt-section">
          <label class="form-label">{{ t('prompt') }}</label>
          <p class="form-help">{{ t('describePromptForModifyingImage') }}</p>
          <el-input
            :model-value="formdata.prompt"
            type="textarea"
            :rows="4"
            :placeholder="t('describeHowImageShouldLook')"
            class="prompt-textarea"
            @update:model-value="handlePromptChange"
          />
        </div>
      </div>

      <!-- 种子值区域 -->
      <div class="form-section">
        <div class="seed-section">
          <label class="form-label">{{ t('seedOptional') }}</label>
          <p class="form-help">{{ t('seedDescription') }}</p>
          <el-input
            :model-value="formdata.seed"
            type="number"
            :placeholder="t('seedPlaceholder')"
            class="seed-input"
            @update:model-value="handleSeedChange"
          />
        </div>
      </div>

      <!-- 高级模式开关 -->
      <div class="form-section">
        <div class="advanced-mode-section">
          <div class="switch-container">
            <div class="switch-labels">
              <label class="form-label">{{ t('advancedMode') }}</label>
              <span class="switch-description">{{ t('muchBetterResult') }}</span>
            </div>
            <el-switch
              :model-value="formdata.advancedMode"
              class="advanced-switch"
              active-color="#2563EB"
              inactive-color="#E5E7EB"
              @update:model-value="handleAdvancedModeChange"
            />
          </div>
        </div>
      </div>
    </div>

    <!-- 生成按钮 -->
    <div class="form-actions">
      <el-button
        :loading="isGenerating"
        :disabled="isButtonDisabled"
        class="generate-button"
        :class="{'disabled': isButtonDisabled}"
        @click="handleGenerate"
        block
      >
        <l-img w="18px" h="18px" src="/static/images/picture-icon.png"></l-img>
        {{ t('generateImage') }}
      </el-button>
    </div>
  </div>
</template>

<script setup>
import { ref, computed, onMounted, onUnmounted, onBeforeUnmount, nextTick } from 'vue';
import { useI18n } from 'vue-i18n';
import UploadImage from '@/components/upload/image.vue';
import LImg from '@/components/l-img.vue';
import { ElMessage } from 'element-plus';
import { useMediaGenerationStore } from '@/store/modules/media-generation';
import { addTaskToPolling, TaskType } from '@/presenter/media-task-polling';
import { mediaTaskEventBus, clearMediaTaskEventListeners } from '@/presenter/media-task-events';
import { IMAGE_OPERATIONS } from '@/types/media-tool';
import router from '@/router';

const { t } = useI18n();
const mediaStore = useMediaGenerationStore();

// 当前模块的 key
const MODULE_KEY = IMAGE_OPERATIONS.EDIT;

const uploadImageRef = ref(null);

const formdata = ref({
      uploadedImage: null,
      uploadedImageUrl: '',
      uploadedImageDimensions: null,
      imageUrl: '',
      prompt: '',
      seed: '',
      advancedMode: false
})
const isGenerating = ref(false);
// 当前任务ID，用于事件过滤
const currentTaskId = ref(null);

// Emits定义 - 只发送四个状态事件
const emit = defineEmits(['generate-success', 'generate-error', 'generate-create', 'loading', 'advancedExpand']);

// Canvas 相关引用
const canvasWrapper = ref(null);
const containerWidth = ref(200); // 设置默认宽度，避免初始为0
const maskCanvas = ref(null);
let ctx = null;
const brushSize = ref(20);
const isDrawing = ref(false);
const lastPoint = ref(null);
const canvasHistory = ref([]);
const historyIndex = ref(-1);

// 计算属性：按钮禁用状态
const isButtonDisabled = computed(() => {
  const hasImage = formdata.value.uploadedImage || formdata.value.uploadedImageUrl || formdata.value.imageUrl;
  return !hasImage || !formdata.value.prompt.trim();
});

const imageClientRect = computed(() => {
  return containerWidth.value + 'px';
});

// 图片加载完成事件处理
const onImageLoad = () => {
  // 图片加载完成后初始化canvas
  nextTick(() => {
    initCanvas();
  });
};

// 初始化canvas
const initCanvas = () => {
  // 1. 检查必要的DOM元素是否存在
  if (!maskCanvas.value || !canvasWrapper.value) {
    console.warn('Canvas or wrapper element not found');
    return;
  }
  
  const canvas = maskCanvas.value;
  const img = canvasWrapper.value.querySelector('.original-image');
  
  // 2. 检查图片元素是否存在
  if (!img) {
    console.warn('Image element not found in canvas wrapper');
    return;
  }
  
  // 注意：此函数在图片onLoad事件后调用，所以图片一定已经加载完成
  
  // 3. 获取图片的实际显示尺寸
  const imgRect = img.getBoundingClientRect();
  if (!imgRect || imgRect.width === 0 || imgRect.height === 0) {
    console.warn('Image dimensions are zero, skipping canvas initialization');
    return;
      }
    
    // 4. 设置画布尺寸与图片显示尺寸相同
    canvas.width = imgRect.width;
    canvas.height = imgRect.height;
    
    // 5. 获取绘图上下文并检查是否成功
  const context = canvas.getContext('2d');
  if (!context) {
    console.error('Failed to get canvas 2D context');
    return;
  }
  
  ctx = context;
  ctx.globalCompositeOperation = 'source-over';
  ctx.strokeStyle = 'rgba(255, 255, 255, 1)'; // 使用白色
  ctx.fillStyle = 'rgba(255, 255, 255, 1)'; // 使用白色
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
    
    // 6. 初始化历史记录：保存初始空白状态
  canvasHistory.value = [];
  historyIndex.value = -1;
  saveCanvasState(); // 保存初始状态，historyIndex变为0
};

// 处理图片上传成功
const handleUploadSuccess = (result) => {
  formdata.value = {
    ...formdata.value,
    uploadedImage: result.originalFile,
    uploadedImageUrl: result.url,
    uploadedImageDimensions: result.dimensions,
    imageUrl: '' // 清空URL输入
  };
};

// 处理图片删除成功
const handleDeleteSuccess = () => {
   formdata.value = {
    ...formdata.value,
    uploadedImage: null,
    uploadedImageUrl: '',
    uploadedImageDimensions: null
   };
     
  // 直接调用清除方法，复用逻辑
   clearMask();
};

// 获取存储的生成结果
const loadGenerationResult = () => {
  const result = mediaStore.getGenerationResult(MODULE_KEY);
  if (result) {
    formdata.value = {
      ...formdata.value,
      uploadedImageUrl: result?.imageUrl
    };
  }
};


// 清除生成结果
const clearGenerationResult = () => {
  mediaStore.clearGenerationResult(MODULE_KEY);
};

// 处理提示词变化
const handlePromptChange = (value) => {
  formdata.value = {
    ...formdata.value,
    prompt: value
  };
};

// 处理种子值变化
const handleSeedChange = (value) => {
    formdata.value = {
    ...formdata.value,
    seed: value
  };
};

// 处理高级模式变化
const handleAdvancedModeChange = (value) => {
    formdata.value = {
    ...formdata.value,
    advancedMode: value
  };
};

// 处理生成按钮点击
const handleGenerate = async () => {
  try {
    // 发送开始生成事件
    emit('generate-create');
    emit('loading', true,null);
    isGenerating.value = true;
    
    // 获取mask数据
    let maskDataURL = null;
    if (maskCanvas.value && ctx) {
      // 检查canvas是否有绘制内容
      const imageData = ctx.getImageData(0, 0, maskCanvas.value.width, maskCanvas.value.height);
      const data = imageData.data;
      let hasContent = false;
      for (let i = 3; i < data.length; i += 4) {
        if (data[i] > 0) { // 检查alpha通道
          hasContent = true;
          break;
        }
      }
      if (hasContent) {
        maskDataURL = maskCanvas.value.toDataURL();
      }
    }
    
    // 准备请求数据
    const requestData = {
      uploadedImage: formdata.value.uploadedImage,
      uploadedImageUrl: formdata.value.uploadedImageUrl,
      uploadedImageDimensions: formdata.value.uploadedImageDimensions,
      prompt: formdata.value.prompt.trim(),
      seed: formdata.value.seed,
      advancedMode: formdata.value.advancedMode,
      maskDataURL: maskDataURL
    };

    console.log('Image editing with data:', requestData);
    
    // TODO: 调用真实的API (暂时忽略，接口不支持)
    // const result = await apiGeneration.imageEdit(requestData);
    
    // 模拟API响应
    const apiResult = {
      task_id: `task_img_edit_${Date.now()}`,
      status: 'pending'
    };
    
    // 设置当前任务ID
    currentTaskId.value = apiResult.task_id;
    
    // 设置路由meta并添加到轮询管理器
    const meta = router.currentRoute.value.meta;
    meta.taskId = apiResult.task_id;
    meta.type = TaskType.IMAGE;
    addTaskToPolling(apiResult.task_id, TaskType.IMAGE);
    
  } catch (error) {
    emit('loading', false,null);
    emit('generate-error', error);
    isGenerating.value = false;
    currentTaskId.value = null;
  }
};

// 处理任务完成事件
const handleTaskCompleted = (res) => {
  if (res && res.taskId === currentTaskId.value) {
    // 构造结果数据
    const result = {
      id: Date.now(),
      imageUrl: res.result?.media_list?.[0]?.file_url || `https://picsum.photos/512/512?random=${Date.now()}`,
      prompt: formdata.value.prompt,
      seed: formdata.value.seed || Math.floor(Math.random() * 1000000),
      advancedMode: formdata.value.advancedMode,
      createdAt: new Date().toISOString()
    };
    
    emit('generate-success', result);
    isGenerating.value = false;
    currentTaskId.value = null;
  }
};

// 处理任务失败事件
const handleTaskFailed = (res) => {
  if (res && res.taskId === currentTaskId.value) {
    emit('generate-error', res);
    isGenerating.value = false;
    currentTaskId.value = null;
  }
};

// 处理任务状态更新事件
const handleTaskStatusUpdate = (res) => {
  if (res && res.taskId === currentTaskId.value) {
    // 更新进度等信息
    console.log(`Image editing progress: ${res.res.progress}%`);
    emit('loading', true, res.res.estimated_time || null);
  }
};

// 移除上传的图片
const removeUploadedImage = () => {
  // 调用子组件的删除方法
  if (uploadImageRef.value) {
    uploadImageRef.value.handleDeleteImage();
  }
  
  formdata.value = {
    ...formdata.value,
    uploadedImage: null,
    uploadedImageUrl: '',
    uploadedImageDimensions: null,
    imageUrl: ''
  };
  
  // 直接调用清除方法，复用逻辑
  clearMask();
};

// 更新容器宽度
const updateContainerWidth = () => {
  if (canvasWrapper.value) {
    const { width } = canvasWrapper.value.getBoundingClientRect();
    if (width > 0) {
      containerWidth.value = width;
    }
  }
};

// ResizeObserver 实例
let resizeObserver = null;

// 获取canvas上的点
const getCanvasPoint = (event) => {
  const canvas = maskCanvas.value;
  if (!canvas) return { x: 0, y: 0 };
  const rect = canvas.getBoundingClientRect();
  const scaleX = canvas.width / rect.width;
  const scaleY = canvas.height / rect.height;
  return {
    x: (event.clientX - rect.left) * scaleX,
    y: (event.clientY - rect.top) * scaleY
  };
};

// 开始绘制
const startDrawing = (event) => {
  if (!ctx || !maskCanvas.value || maskCanvas.value.width === 0 || maskCanvas.value.height === 0) return;
  
  // 移除这里的保存，开始绘制时不保存
  
  isDrawing.value = true;
  const point = getCanvasPoint(event);
  lastPoint.value = point;
  ctx.lineWidth = brushSize.value;
  ctx.beginPath();
  ctx.arc(point.x, point.y, brushSize.value / 2, 0, 2 * Math.PI);
  ctx.fill();
};

// 绘制中
const draw = (event) => {
  if (!isDrawing.value || !ctx || !maskCanvas.value || !lastPoint.value) return;
  const currentPoint = getCanvasPoint(event);
  ctx.lineWidth = brushSize.value;
  ctx.beginPath();
  ctx.moveTo(lastPoint.value.x, lastPoint.value.y);
  ctx.lineTo(currentPoint.x, currentPoint.y);
  ctx.stroke();
  lastPoint.value = currentPoint;
};

// 停止绘制
const stopDrawing = () => {
  if (!isDrawing.value) return; // 如果没有在绘制，不需要保存
  
  isDrawing.value = false;
  lastPoint.value = null;
  
  // 绘制完成后保存状态
  saveCanvasState();
};

// 触摸事件
const handleTouchStart = (event) => {
  event.preventDefault();
  if (event.touches.length === 1) {
    const touch = event.touches[0];
    const mouseEvent = new MouseEvent('mousedown', {
      clientX: touch.clientX,
      clientY: touch.clientY,
    });
    startDrawing(mouseEvent);
  }
};
const handleTouchMove = (event) => {
  event.preventDefault();
  if (event.touches.length === 1 && isDrawing.value) {
    const touch = event.touches[0];
    const mouseEvent = new MouseEvent('mousemove', {
      clientX: touch.clientX,
      clientY: touch.clientY,
    });
    draw(mouseEvent);
  }
};
const handleTouchEnd = (event) => {
  event.preventDefault();
  stopDrawing();
};
const preventDefault = (event) => {
  event.preventDefault();
  return false;
};

// 清空mask
const clearMask = () => {
  if (ctx && maskCanvas.value) {
    ctx.clearRect(0, 0, maskCanvas.value.width, maskCanvas.value.height);
    
    // 清空后重置历史记录到初始状态
    const imageData = ctx.getImageData(0, 0, maskCanvas.value.width, maskCanvas.value.height);
    canvasHistory.value = [imageData]; // 历史数组长度重置为1，只保留当前空白状态
    historyIndex.value = 0; // 激活下标重置为0
  }
};
// 保存画布状态
const saveCanvasState = () => {
  if (!maskCanvas.value || !ctx) return;
  const canvas = maskCanvas.value;
  if (canvas.width === 0 || canvas.height === 0) return;
  
  try {
    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    
    // 检查是否需要截断：如果激活下标小于数组长度-1，说明用户撤销后又重绘了
    if (historyIndex.value < canvasHistory.value.length - 1) {
      // 截断：保留0到激活下标的记录
      canvasHistory.value = canvasHistory.value.slice(0, historyIndex.value + 1);
    }
    
    // 添加新状态
    canvasHistory.value.push(imageData);
    historyIndex.value = canvasHistory.value.length - 1; // 激活下标指向最新记录
    
    // 限制历史记录数量（最多20个）
    if (canvasHistory.value.length > 20) {
      canvasHistory.value.shift();
      historyIndex.value--;
    }
    
  } catch (error) {
    console.warn('Failed to save canvas state:', error);
  }
};
// 撤销
const undoMask = () => {
  // 历史数组长度必须大于等于1，且激活下标大于0才能撤销
  if (!ctx || !maskCanvas.value || canvasHistory.value.length < 1 || historyIndex.value <= 0) return;
  
  try {
    historyIndex.value--; // 激活下标-1
    const imageData = canvasHistory.value[historyIndex.value];
    ctx.putImageData(imageData, 0, 0);
  } catch (error) {
    console.warn('Failed to undo:', error);
  }
};
// 重做
const redoMask = () => {
  // 激活下标必须小于历史长度-1才能重做
  if (!ctx || !maskCanvas.value || historyIndex.value >= canvasHistory.value.length - 1) return;
  
  try {
    historyIndex.value++; // 激活下标+1
    const imageData = canvasHistory.value[historyIndex.value];
    ctx.putImageData(imageData, 0, 0);
  } catch (error) {
    console.warn('Failed to redo:', error);
  }
};
// 下载mask
const downloadMask = () => {
  if (!maskCanvas.value || maskCanvas.value.width === 0 || maskCanvas.value.height === 0) {
    ElMessage.warning(t('noMaskToDownload'));
    return;
  }
  try {
    const link = document.createElement('a');
    link.download = 'mask.png';
    link.href = maskCanvas.value.toDataURL();
    link.click();
    ElMessage.success(t('maskDownloadedSuccessfully'));
  } catch (error) {
    console.error('Failed to download mask:', error);
    ElMessage.error(t('failedToDownloadMask'));
  }
};

// 工具栏按钮事件处理
const handleUndoMask = () => {
  undoMask();
};

const handleRedoMask = () => {
  redoMask();
};

const handleClearMask = () => {
  clearMask();
};

const handleDownloadMask = () => {
  downloadMask();
};

// canvas初始化与事件绑定

onMounted(() => {
  // 初始化容器宽度
  updateContainerWidth();
  
  // 创建 ResizeObserver 监听容器尺寸变化
  if (canvasWrapper.value && window.ResizeObserver) {
    resizeObserver = new ResizeObserver((entries) => {
      for (const entry of entries) {
        const { width } = entry.contentRect;
        if (width > 0) {
          containerWidth.value = width;
        }
      }
    });
    resizeObserver.observe(canvasWrapper.value);
  } else {
    // 降级处理：监听窗口resize事件
    window.addEventListener('resize', updateContainerWidth);
  }
  
  // 获取之前保存的生成结果
  loadGenerationResult();
  
  // 绑定媒体任务事件监听器（只绑定一次）
  mediaTaskEventBus.on('task-completed', handleTaskCompleted);
  mediaTaskEventBus.on('task-failed', handleTaskFailed);
  mediaTaskEventBus.on('task-status-update', handleTaskStatusUpdate);
});

// 组件卸载前清理生成结果
onBeforeUnmount(() => {
  clearGenerationResult();
  // 清理事件监听器（只清理一次）
  clearMediaTaskEventListeners();
});

// 组件卸载时清理
onUnmounted(() => {
  if (resizeObserver) {
    resizeObserver.disconnect();
    resizeObserver = null;
  } else {
    window.removeEventListener('resize', updateContainerWidth);
  }
});
</script>

